// WF09 v1 - Validación del payload + preparación de todos los derivados.
//
// Output: un único item con todo lo necesario para los nodos HTTP siguientes:
//   - config: { evoapi_base_url, evoapi_instance }
//   - group_subject, participants, video_url, segment
//   - lead, closer (closer = null si modo "sin closer"), meeting
//   - messages: array de strings (3 o 5 según closer)
//
// Las llamadas a Evolution API se hacen en nodos HTTP Request nativos (el
// modo task runner del Code node no permite httpRequestWithAuthentication).

const EVOAPI_BASE_URL = 'https://cioevolutionapiapp.nexau.es';
const EVOAPI_INSTANCE = 'Leon-Test';

// Foto de perfil corporativa de C.io. Se aplica a TODOS los grupos creados
// por el workflow. Hosteada en Google Drive (link "Anyone with the link").
// Si rotamos foto: subir nueva versión y actualizar este URL.
const GROUP_PICTURE_URL = 'https://drive.google.com/uc?export=download&id=1WRAzcFPSphrJCaEgPUWcMFCJh4TuIuup';

const VIDEO_BY_SEGMENT = {
  genesis: 'https://privado.consultoria.io/nuestra-estrategia',
  mega:    'https://ia.consultoria.io/proceso-en-detalle',
};

function normalizePhone(raw) {
  if (!raw) return null;
  const digits = String(raw).replace(/\D/g, '');
  if (digits.length < 8) return null;
  return digits;
}

function fail(msg) {
  throw new Error('WF09 payload error: ' + msg);
}

const payload = $input.first().json.body || $input.first().json;

const required = ['lead_id', 'lead_name', 'lead_phone', 'lead_company', 'meeting_url', 'meeting_at', 'segment'];
for (const k of required) {
  if (!payload[k]) fail('missing field ' + k);
}

const lead_phone = normalizePhone(payload.lead_phone);
if (!lead_phone) fail('lead_phone is not a valid E.164 number');

let closer = null;
if (payload.closer_name || payload.closer_phone) {
  if (!payload.closer_name || !payload.closer_phone) {
    fail('closer_name and closer_phone must both be provided together (or both omitted)');
  }
  const closer_phone = normalizePhone(payload.closer_phone);
  if (!closer_phone) fail('closer_phone is not a valid E.164 number');
  closer = { name: payload.closer_name, phone: closer_phone };
}

const segment = String(payload.segment).toLowerCase();
if (!VIDEO_BY_SEGMENT[segment]) fail('segment must be genesis or mega, got ' + segment);
const video_url = VIDEO_BY_SEGMENT[segment];

const stakeholders = Array.isArray(payload.stakeholders) ? payload.stakeholders : [];
const stakeholder_phones = [];
for (const sh of stakeholders) {
  const p = normalizePhone(sh.phone);
  if (!p) fail('stakeholder phone invalid: ' + JSON.stringify(sh));
  stakeholder_phones.push(p);
}

const meetingDate = new Date(payload.meeting_at);
if (isNaN(meetingDate.getTime())) fail('meeting_at is not a valid ISO date');

const fmtMadridParts = new Intl.DateTimeFormat('es-ES', {
  timeZone: 'Europe/Madrid',
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
}).formatToParts(meetingDate).reduce((acc, p) => { acc[p.type] = p.value; return acc; }, {});
const dateStr = `${fmtMadridParts.day}/${fmtMadridParts.month}/${fmtMadridParts.year}`;
const timeStr = `${fmtMadridParts.hour}:${fmtMadridParts.minute}`;
const hourLabel = fmtMadridParts.hour + 'h';
const group_subject = `${payload.lead_company} x C.io - ${dateStr} a las ${hourLabel}`;

const participants = [lead_phone, ...stakeholder_phones];
if (closer) participants.unshift(closer.phone);

const lead = { id: payload.lead_id, name: payload.lead_name, phone: lead_phone, company: payload.lead_company };
const meeting = { url: payload.meeting_url, at_iso: payload.meeting_at, date_madrid: dateStr, time_madrid: timeStr };

const messages = closer
  ? [
      `Hola ${lead.name}, ${closer.name}, os presento`,
      `${lead.name} es el fundador de ${lead.company}`,
      `${closer.name} es uno de nuestros consultores expertos en ecommerce`,
      `Os dejo por aquí el enlace para la reunión: ${meeting.url}`,
      `Por cierto, ${lead.name}, te dejo por aquí el vídeo que te había comentado para que puedas verlo antes de la llamada ${video_url}`,
    ]
  : [
      `Hola ${lead.name} 👋`,
      `Te dejo por aquí el enlace para la reunión: ${meeting.url}`,
      `Por cierto, te dejo por aquí el vídeo que te había comentado para que puedas verlo antes de la llamada ${video_url}`,
    ];

return [{
  json: {
    config: { evoapi_base_url: EVOAPI_BASE_URL, evoapi_instance: EVOAPI_INSTANCE, group_picture_url: GROUP_PICTURE_URL },
    lead,
    closer,
    meeting,
    segment,
    video_url,
    group_subject,
    participants,
    messages,
  }
}];

// WF09 v1 - Toma la respuesta de Create group + los datos validados y produce
// N items (uno por mensaje a enviar). Cada item lleva todo lo necesario para
// que el siguiente nodo HTTP haga sendText sin más lookups.
//
// NOTA: el nodo inmediatamente anterior es "Set group picture" (cuya response
// es {update: success} y no nos sirve para nada aquí), por eso accedemos
// explícitamente a "Create group" por nombre para sacar el groupJid.

const createResp = $('Create group').first().json;
const validated = $('Validate payload').first().json;

const groupJid = createResp?.id || createResp?.groupJid || createResp?.group?.id;
if (!groupJid) {
  throw new Error('Create group: no groupJid in response: ' + JSON.stringify(createResp).slice(0, 500));
}

const items = [];
for (let i = 0; i < validated.messages.length; i++) {
  items.push({
    json: {
      config: validated.config,
      group_jid: groupJid,
      group_subject: validated.group_subject,
      total: validated.messages.length,
      index: i + 1,
      text: validated.messages[i],
    }
  });
}
return items;

// WF09 v1 - Combina las N respuestas de Send text en un único response final.
//
// onError=continueRegularOutput en Send text hace que las llamadas que fallan
// pasen como items con `error` en lugar de abortar el flujo. Aquí marcamos
// cada índice como ok/no-ok y devolvemos un sent[] análogo al SOP original.

const responses = $input.all();
const builtItems = $('Build message items').all();
const validated = $('Validate payload').first().json;

const sent = [];
for (let i = 0; i < responses.length; i++) {
  const r = responses[i];
  const errObj = r.json?.error || r.error;
  sent.push({
    index: i + 1,
    ok: !errObj,
    text: builtItems[i]?.json?.text,
    message_id: r.json?.key?.id || r.json?.id || null,
    error: errObj ? (errObj.message || String(errObj)) : undefined,
  });
}

const groupJid = builtItems[0]?.json?.group_jid;

return [{
  json: {
    ok: sent.length > 0 && sent.every(s => s.ok),
    group_jid: groupJid,
    group_subject: validated.group_subject,
    lead_id: validated.lead.id,
    meeting_at: validated.meeting.at_iso,
    mode: validated.closer ? 'with_closer' : 'no_closer',
    sent,
  }
}];
